/*
 * A052025  Every prefix (or suffix) of palindromic prime a(n) is prime
 *          (right/left-truncatable).
 * https://oeis.org/A052025
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full
 * Formula:   a(n) = the n-th palindromic prime whose every prefix (and
 *            consequently every suffix) is also prime. The values are
 *            generated by exhaustive search
 * Range:     u8 n <= 4, u16 n <= 7, u32 n <= 7, u64 n <= 7, u128 n <= 7,
 *            big any n
 * Helpers:   get_digits, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/is_prime_big.h"
#include "../utils/get_digits.h"

/* Construct a palindrome from the given half.
   `half` contains the first ceil(len/2) digits of the palindrome. */
static seq_t make_palindrome(uint64_t half, idx_t len)
{
    seq_t num = (seq_t)half;
    uint64_t temp = half;
    if (len & 1)            /* odd length: skip the middle digit in reverse */
        temp /= 10;
    while (temp > 0) {
        num = num * 10 + (seq_t)(temp % 10);
        temp /= 10;
    }
    return num;
}

/* Return true if every proper prefix and suffix of `num` is prime. */
static bool is_truncatable(seq_t num)
{
    uint8_t buf[64];
    size_t len;
    get_digits(num, buf, &len);

    /* prefixes */
    seq_t prefix = 0;
    for (size_t i = 0; i < len; ++i) {
        prefix = prefix * 10 + (seq_t)buf[i];
        if (!is_prime_big(prefix))
            return false;
    }

    /* suffixes */
    for (size_t k = 1; k < len; ++k) {
        seq_t suffix = 0;
        for (size_t j = len - k; j < len; ++j) {
            suffix = suffix * 10 + (seq_t)buf[j];
        }
        if (!is_prime_big(suffix))
            return false;
    }

    return true;
}

/* Auxiliary: compute 10^e using 64‑bit arithmetic.  e is small. */
static uint64_t pow10_uint64(idx_t e)
{
    uint64_t r = 1;
    while (e--)
        r *= 10;
    return r;
}

seq_t a(idx_t n)
{
    idx_t count = 0;                    /* how many terms found */
    for (idx_t len = 1; ; ++len) {      /* increase palindrome length */
        if (len == 1) {                 /* 1‑digit primes */
            seq_t single[4] = {(seq_t)2, (seq_t)3, (seq_t)5, (seq_t)7};
            for (int i = 0; i < 4; ++i) {
                ++count;
                if (count == n)
                    return single[i];
            }
        } else {
            idx_t half_len = (len + 1) / 2;
            uint64_t start = pow10_uint64(half_len - 1);
            uint64_t end   = pow10_uint64(half_len) - 1;
            for (uint64_t half = start; half <= end; ++half) {
                seq_t num = make_palindrome(half, len);
                if (!is_prime_big(num))
                    continue;
                if (!is_truncatable(num))
                    continue;
                ++count;
                if (count == n)
                    return num;
            }
        }
    }
    /* control never reaches here */
    return 0;
}
